# Generated by gen_preproc_final_expected.py (mne 1.13.2)
import math
import numpy as np
import mne
from mne.preprocessing import (maxwell_filter, compute_maxwell_basis, compute_proj_hfc,
                               read_fine_calibration, write_fine_calibration)


def near(name: str, a: float, b: float, rtol: float = 1e-6, atol: float = 1e-18):
    if abs(a - b) > atol + rtol * abs(b):
        print("TEST FAILED:", name, a, b)


def cross(a, b):
    return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]


def meg_info(n_mag: int = 40, n_grad: int = 40, sfreq: float = 200.0):
    n = n_mag + n_grad
    names = [f"MEG{i + 1:04d}" for i in range(n)]
    types = ["mag" for _ in range(n_mag)] + ["grad" for _ in range(n_grad)]
    info = mne.create_info(names, sfreq, types)
    for i in range(n):
        th = math.acos(1.0 - 0.9 * (i + 0.5) / n)
        ph = 2.399963 * i
        pos = [0.11 * math.sin(th) * math.cos(ph), 0.11 * math.sin(th) * math.sin(ph), 0.11 * math.cos(th)]
        nrm = math.sqrt(pos[0] ** 2 + pos[1] ** 2 + pos[2] ** 2)
        ez = [pos[0] / nrm, pos[1] / nrm, pos[2] / nrm]
        ex = cross([0.0, 0.0, 1.0], ez)
        nx = math.sqrt(ex[0] ** 2 + ex[1] ** 2 + ex[2] ** 2)
        if nx < 1e-8:
            ex = [1.0, 0.0, 0.0]
        else:
            ex = [ex[0] / nx, ex[1] / nx, ex[2] / nx]
        ey = cross(ez, ex)
        info.locs[i] = pos + ex + ey + ez
        info.coil_types[i] = 3022 if types[i] == "mag" else 3012
    return info


def make_raw():
    info = meg_info()
    rng = np.random.RandomState(2)
    d = rng.randn(80, 2000) * 1e-13
    t = np.arange(2000) / 200.0
    d += 1e-12 * np.sin(2 * np.pi * 7 * t)[None, :] * rng.randn(80, 1)
    d[40:] *= 0.01
    return mne.io.RawArray(d, info)


raw = make_raw()
org = (0.0, 0.0, 0.04)


def test_sss():
    r1 = maxwell_filter(raw, origin=org, coord_frame="meg", int_order=6, ext_order=2, bad_condition="ignore")
    d1 = r1.get_data()
    near("sss_abs", float(np.abs(d1).sum()), 4.2413400761925844e-06)
    near("sss_3_100", float(d1[3, 100]), 7.13461151272563e-13)
    near("sss_50_500", float(d1[50, 500]), 2.824283673697685e-12)
    near("sss_col0", float(d1[:, 0].sum()), -1.9978549404679523e-12)
    r3 = maxwell_filter(raw, origin=org, coord_frame="meg", int_order=6, ext_order=2, regularize=None,
                        bad_condition="ignore")
    near("noreg", float(np.abs(r3.get_data()).sum()), 0.0006858320877297678)

test_sss()


def test_tsss():
    r2 = maxwell_filter(raw, origin=org, coord_frame="meg", int_order=6, ext_order=2, st_duration=4.0,
                        st_correlation=0.9, bad_condition="ignore")
    d2 = r2.get_data()
    near("tsss_abs", float(np.abs(d2).sum()), 4.472749071183257e-08)
    near("tsss_3_100", float(d2[3, 100]), 1.6281738442097652e-13)
    near("tsss_50_500", float(d2[50, 500]), 2.921140120686211e-13)

test_tsss()


def test_bads():
    rb = raw.copy()
    rb.info.bads = ["MEG0005"]
    r4 = maxwell_filter(rb, origin=org, coord_frame="meg", int_order=6, ext_order=2, bad_condition="ignore")
    near("bads_abs", float(np.abs(r4.get_data()).sum()), 2.146659518974246e-06)
    assert len(r4.info.bads) == 0

test_bads()


def test_basis():
    S, pS, rm, nin = compute_maxwell_basis(raw.info, origin=org, int_order=6, ext_order=2, coord_frame="meg",
                                           regularize="in", ignore_ref=True, bad_condition="ignore")
    assert S.shape[0] == 80 and S.shape[1] == 51
    assert pS.shape[0] == 51 and pS.shape[1] == 80
    assert rm.shape[0] == 51
    assert nin == 43
    near("basis_S", float(np.abs(S).sum()), 3577210.967196847, 1e-6, 0.0)
    near("basis_pS", float(np.abs(pS).sum()), 2998907137.955312, 1e-6, 0.0)
    near("basis_S53", float(S[5, 3]), -0.03189124621635052, 1e-6, 0.0)

test_basis()


def test_hfc():
    pr = compute_proj_hfc(raw.info, order=2)
    assert len(pr) == 8
    near("hfc0", float(np.abs(pr[0].data).sum()), 5.407561478759812, 1e-6, 0.0)
    near("hfc4", float(pr[4].data[0, 7]), 0.04529189396253633, 1e-6, 0.0)
    assert pr[3].desc == "HFC: l=2 m=-2"

test_hfc()


def test_fine_cal_io():
    p = "/tmp/typhon_fc.dat"
    names = ["113", "2642", "1"]
    txt = "# comment\n"
    for i in range(3):
        vals = " ".join([f"{k * 0.01 + i:.6f}" for k in range(12)])
        txt += names[i] + " " + vals + " 1.012300\n"
    f = open(p, "w")
    f.write(txt)
    f.close()
    nm, locs, imb = read_fine_calibration(p)
    assert nm[0] == "MEG0113" and nm[1] == "MEG2642" and nm[2] == "1"
    assert locs.shape[0] == 3 and locs.shape[1] == 12
    near("fc_locs", float(locs.sum()), 37.98, 1e-9, 0.0)
    assert abs(imb[1][0] - 1.0123) < 1e-12
    p2 = "/tmp/typhon_fc2.dat"
    write_fine_calibration(p2, nm, locs, imb)
    nm2, locs2, imb2 = read_fine_calibration(p2)
    assert nm2[0] == "MEG0113" and nm2[2] == "1"
    near("fc_rt", float(locs2.sum()), 37.98, 1e-9, 0.0)

test_fine_cal_io()
